  (* [comment removed for export] *)
  Section AfterRefill.
    Variables (m1 m2 : mem) (q0 q1 q2 q3 : word).
    Hypothesis MU1 : munch Wh m m1.
    Hypothesis WM1 : wmono bsegs m m1.
    Hypothesis MU2 : munch Wf m1 m2.
    Hypothesis WM2 : wmono bsegs m1 m2.
    Hypothesis MI0 : mem_inv bsegs m.
    Hypothesis MI2 : mem_inv bsegs m2.
    (* [comment removed for export] *)
    Hypothesis PCN : rw_cells bsegs m2 P [C4 (wz n)].
    Hypothesis FAM2 : forall c', 1 <= c' <= 31 -> rw_cells bsegs m2 (CA + 80 * c' + 4) [C4 (wz (max_count c'))] /\ rw_cells bsegs m2 (CA + 80 * c' + 8) [C8 (wz (class_size c'))].
    Hypothesis CHA : u32arr bsegs m2 (P + 16) (wlist (rev (firstn (Z.to_nat n) fl1))).
    Hypothesis CHJ : stk bsegs m2 (P + 16 + 4 * n) (P + 80).
    Hypothesis RI2 : rw_cells bsegs m2 RI [C8 (wz 0); C4 (wz 0); C4 (wz 0); C8 (wz (nf1 - n)); C8 (wz mfa'); C8 (wz au'); C8 (wz 0); C8 (wz mu'); C8 (wz 0)].
    Hypothesis RIJ2 : stk bsegs m2 (RI + 64) (RI + 68).
    Hypothesis EXH2 : rw_cells bsegs m2 (RI + 68) [C1 (b8 0)].
    Hypothesis RST2 : stk bsegs m2 (RI + 69) (RI + 128).
    Hypothesis FARR2 : u32arr bsegs m2 (FA s c) (wlist (rev fl1)).
    Hypothesis FAJ2 : stk bsegs m2 (FA s c + 4 * nf1) (FA s c + mfa').
    Hypothesis USJ2 : stk bsegs m2 (RB s c + au) (RB s c + mu').
    Hypothesis POIu2 : poisoned m2 (RB s c + mu) (Z.to_nat ((mu' - mu) / 8)) 0xfa.
    Hypothesis POIf2 : poisoned m2 (FA s c + mfa) (Z.to_nat ((mfa' - mfa) / 8)) 0xfa.
    Hypothesis QST2 : rw_cells bsegs m2 (TH + 2768) [C8 q0; C8 q1; C8 q2; C8 q3].
    Hypothesis TST2 : stk bsegs m2 (TH + 2800) (TH + 3168).
    (* [comment removed for export] *)
    Hypothesis UNW1 : rw_cells bsegs m1 (TH + 3168) [C1 (b8 0)].

    Definition free_mR : mem := chim Wo m m2.
    Let mR := free_mR.

    (* [comment removed for export] *)
    Ltac wfsplit := unfold Wf, rf_W; cbn [outside];
      repeat lazymatch goal with
        | |- _ /\ _ => split
        | |- outside (icW _) _ => apply outside_icW_far; tlia
        | |- True => exact I
        | |- ~ _ => tlia
        end.
