    (* [comment removed for export] *)
    Theorem after_refill_bundle : forall (b1 actx idv hdq qbytes : Z),
      rw_cells bsegs m1 (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)] ->
      rw_cells bsegs m1 U [C8 (wz idv)] ->
      rw_cells bsegs m1 AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)] -> ia_after m1 ->
      u8arr bsegs m1 (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))) ->
      rw_cells bsegs m1 (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz qbytes)] ->
      (k <> 0 -> rw_cells bsegs m1 LA [C8 (wz 0)] /\ rw_cells bsegs m1 (LA + 16) [C8 (wz kBatchCount)]) ->
      rw_cells bsegs m (AINST + OI_SPACEBEG) [C8 (wz sb)] ->
         (AREP sR mR /\ mem_inv bsegs mR /\ wmono bsegs m mR /\ agree_on (outside WR) m mR /\ (flagsx_rep m -> flagsx_rep mR))
      /\ (B = sb + c * 2^32 + cp * 16 /\ AHI_LO <= B /\ B + kBatchSize <= aceil /\ (TH + 4096 <= B \/ B + kBatchSize <= TH) /\ (B + kBatchSize <= U - 16 \/ U + 8 <= B)
          /\ (d_nb d + 16 * 65536 <= B \/ B + kBatchSize <= d_nb d) /\ (d_sb d + 8 * 262144 <= B \/ B + kBatchSize <= d_sb d) /\ 0 < B
          /\ (k <> 0 -> B + kBatchSize <= LA \/ LA + kBatchSize <= B))
