      Lemma head_cells3 : forall (b1 actx idv : Z),
        rw_cells bsegs m2 (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)] ->
        rw_cells bsegs m2 U [C8 (wz idv)] ->
        rw_cells bsegs m2 AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)] -> ia_after m2 ->
        u8arr bsegs m2 (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size))) ->
        rw_cells bsegs m2 (TH + 3168) [C1 (b8 0)] ->
           rw_cells bsegs m3 (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)]
        /\ rw_cells bsegs m3 U [C8 (wz idv)]
        /\ rw_cells bsegs m3 AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)] /\ ia_after m3
        /\ u8arr bsegs m3 (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size)))
        /\ stk bsegs m3 (TH + 2800) (TH + 3168)
        /\ rw_cells bsegs m3 (TH + 3168) [C1 (b8 0)]
